const times=[{year:'1924',label:['THE BEGINNING','EL COMIENZO'],title:['An icon<br><i>is born.</i>','Nace<br><i>un ícono.</i>'],copy:['Imperial began in Costa Rica in 1924. A local story that would go on to span generations.','Imperial nació en Costa Rica en 1924. Una historia local que llegaría a acompañar a varias generaciones.'],url:'https://www.fifco.com/bajo-la-campana-historias-para-celebrar/'},{year:'2024',label:['A CENTURY OF STORIES','UN SIGLO DE HISTORIAS'],title:['One hundred years.<br><i>Countless memories.</i>','Cien años.<br><i>Incontables recuerdos.</i>'],copy:['In 2024, Imperial celebrated its centenary. FIFCO’s “Historias para celebrar” campaign paid tribute to Costa Rican cultural and environmental richness.','En 2024, Imperial celebró su centenario. La campaña de FIFCO “Historias para celebrar” rindió homenaje a la riqueza cultural y ambiental de Costa Rica.'],url:'https://www.fifco.com/bajo-la-campana-historias-para-celebrar/'},{year:'NEXT',label:['THE MUSEUM CHAPTER','EL CAPÍTULO DEL MUSEO'],title:['A new home<br><i>for the story.</i>','Un nuevo lugar<br><i>para la historia.</i>'],copy:['Museo Imperial is a new cultural concept envisioned for La Fortuna by Arenal Prime Group. The project and final exhibition are in development.','Museo Imperial es un nuevo concepto cultural concebido para La Fortuna por Arenal Prime Group. El proyecto y la exposición final están en desarrollo.'],url:'/experience/'}];
