$$('[data-interior]').forEach(b=>b.addEventListener('click',()=>{currentObject=+b.dataset.interior;renderObject();openModal('#object-dialog')}));
function renderChapter(){if(!$('#chapter-panel'))return;const c=chapters[chapter];$('#chapter-image').src='/assets/'+c.image+'.webp';$('#chapter-image').alt=c.alt;$('#chapter-image').style.objectPosition=chapter==='design'?'80% center':'center';$('#chapter-label').textContent=tr(...c.label);$('#chapter-title').innerHTML=tr(...c.title);$('#chapter-description').textContent=tr(...c.copy);$('#chapter-link').href=c.url;$('#chapter-link').textContent=tr(...c.cta);$('#chapter-panel').setAttribute('aria-labelledby','chapter-'+chapter);$$('[data-chapter]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.chapter===chapter);b.tabIndex=b.dataset.chapter===chapter?0:-1})}
function renderTime(){if(!$('#timeline-year'))return;const item=times[time];$('#timeline-year').textContent=time===2?tr('NEXT','HOY'):item.year;$('#timeline-tag').textContent=tr(...item.label);$('#timeline-title').innerHTML=tr(...item.title);$('#timeline-copy').textContent=tr(...item.copy);const a=$('#timeline-source');a.href=item.url;a.textContent=time===2?tr('EXPLORE THE CONCEPT','EXPLORAR EL CONCEPTO'):'SOURCE / FIFCO';a.target=time===2?'_self':'_blank';$('#timeline-story').textContent=tr(...item.copy);$('#timeline-story').setAttribute('aria-labelledby','time-'+time);$$('[data-time]').forEach(b=>{b.setAttribute('aria-selected',+b.dataset.time===time);b.tabIndex=+b.dataset.time===time?0:-1})}
function renderObject(){const o=objects[currentObject];$('#object-image').src='/assets/'+o.image+'.webp';$('#object-image').alt=tr(...o.title).replace(/<[^>]*>/g,' ');$('#object-number').textContent=(currentObject>=4?'':'NO. ')+o.no;$('#object-disclaimer').textContent=currentObject>=5?tr('ARCHITECTURAL CONCEPT RENDER · FINAL DESIGN IN DEVELOPMENT','RENDER ARQUITECTÓNICO CONCEPTUAL · DISEÑO FINAL EN DESARROLLO'):currentObject===4?tr('PLANNED INSTALLATION · CONCEPT VISUALIZATION','INSTALACIÓN PREVISTA · VISUALIZACIÓN CONCEPTUAL'):tr('VISUAL INTERPRETATION · NOT AN AUTHENTICATED MUSEUM OBJECT','INTERPRETACIÓN VISUAL · NO ES UNA PIEZA DE MUSEO AUTENTICADA');$('#object-title').innerHTML=tr(...o.title);$('#object-description').textContent=tr(...o.copy);zoom=1;renderZoom()}
function renderZoom(){$('#object-image').style.transform=`scale(${zoom})`;$('#zoom-value').textContent=Math.round(zoom*100)+'%';$('#zoom-out').disabled=zoom<=1;$('#zoom-in').disabled=zoom>=2}
function translate(){document.documentElement.lang=lang;$$('[data-en]').forEach(el=>el.innerHTML=el.dataset[lang]);$('#language').textContent=lang==='en'?'EN / ES':'ES / EN';$('#language').setAttribute('aria-label',tr('Cambiar a español','Switch to English'));renderChapter();renderTime();if($('#object-dialog').open)renderObject()}
$('#language').addEventListener('click',()=>{lang=lang==='en'?'es':'en';try{localStorage.setItem('imperial-language',lang)}catch{}translate()});
