$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));$$('[data-object]').forEach(x=>x.hidden=filter!=='all'&&x.dataset.category!==filter);$('.collection-grid').classList.toggle('filtered',filter!=='all')}));
const mt=$('#menu-toggle');mt.addEventListener('click',()=>{const open=mt.getAttribute('aria-expanded')!=='true';mt.setAttribute('aria-expanded',open);$('#mobile-menu').hidden=!open});$('#mobile-menu').addEventListener('click',e=>{if(e.target.closest('a')){mt.setAttribute('aria-expanded','false');$('#mobile-menu').hidden=true}});
let lastFocus=null;function openModal(id){lastFocus=document.activeElement;$(id).showModal();document.body.style.overflow='hidden'}$$('[data-contact]').forEach(b=>b.addEventListener('click',()=>openModal('#contact-dialog')));$$('[data-object]').forEach(b=>b.addEventListener('click',()=>{currentObject=+b.dataset.object;renderObject();openModal('#object-dialog')}));$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>{d.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus()});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$('#zoom-in').addEventListener('click',()=>{zoom=Math.min(2,zoom+.25);renderZoom()});$('#zoom-out').addEventListener('click',()=>{zoom=Math.max(1,zoom-.25);renderZoom()});$('#object-prev').addEventListener('click',()=>{currentObject=(currentObject+objects.length-1)%objects.length;renderObject()});$('#object-next').addEventListener('click',()=>{currentObject=(currentObject+1)%objects.length;renderObject()});$('#object-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft')$('#object-prev').click();if(e.key==='ArrowRight')$('#object-next').click()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#mobile-menu').hidden=true;mt.setAttribute('aria-expanded','false')}});
$('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const interest=$('select[name=interest]').selectedOptions[0].textContent;const body=tr('Hello Arenal Prime Group,','Hola Arenal Prime Group,')+'\n\n'+tr('My name is ','Mi nombre es ')+f.get('name')+'.\n'+tr('I am interested in: ','Me interesa: ')+interest+'.\n\n'+f.get('message')+'\n\n'+tr('I understand Museo Imperial is a project in development.','Entiendo que Museo Imperial es un proyecto en desarrollo.');$('#form-status').textContent=tr('Your enquiry is ready. Send it from your email app. You may also write to andres@arenalprimegroup.com.','Tu consulta está lista. Enviála desde tu aplicación de correo. También podés escribir a andres@arenalprimegroup.com.');location.href='mailto:andres@arenalprimegroup.com?subject='+encodeURIComponent('Museo Imperial — '+interest)+'&body='+encodeURIComponent(body)});
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let lastY=0,ticking=false;function updateScroll(){const y=scrollY;$('#header').classList.toggle('fixed',y>140);$('#header').classList.toggle('hidden-header',y>400&&y>lastY&&$('#mobile-menu').hidden&&!$('#header').contains(document.activeElement));lastY=y;const max=document.documentElement.scrollHeight-innerHeight;$('#reading-progress').style.width=(max?100*y/max:0)+'%';ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(updateScroll);ticking=true}},{passive:true});
if(!reduce&&'IntersectionObserver'in window){document.body.classList.add('js');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});$$('.intro-grid,.section-heading,.timeline-content,.space-copy,.visit-text,.statement>p').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}
